#!/usr/bin/python3
# SPDX-License-Identifier: GPL-3.0-or-later

"""Build OSTree-bound UKIs from the GRUB menu generated by Deepin."""

from __future__ import annotations

import argparse
import fcntl
import hashlib
import os
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path


class ManagerError(RuntimeError):
    pass


@dataclass(frozen=True)
class BootEntry:
    title: str
    kernel: str
    initrds: tuple[str, ...]
    cmdline: str
    ostree: str

    @property
    def deployment_id(self) -> str:
        match = re.search(r"/([^/]+)/checkout/?$", self.ostree)
        if match:
            return match.group(1)
        return hashlib.sha256(self.ostree.encode()).hexdigest()[:16]


def _code_and_brace_delta(line: str) -> tuple[str, int]:
    """Remove GRUB comments and count braces outside strings."""
    out: list[str] = []
    quote: str | None = None
    escaped = False
    delta = 0
    for char in line:
        if escaped:
            out.append(char)
            escaped = False
            continue
        if char == "\\":
            out.append(char)
            escaped = True
            continue
        if quote:
            out.append(char)
            if char == quote:
                quote = None
            continue
        if char in ("'", '"'):
            quote = char
            out.append(char)
        elif char == "#":
            break
        elif char == "{":
            delta += 1
            out.append(char)
        elif char == "}":
            delta -= 1
            out.append(char)
        else:
            out.append(char)
    return "".join(out), delta


def parse_top_level_entries(config: str) -> list[BootEntry]:
    """Parse top-level menuentry blocks, intentionally ignoring submenus."""
    blocks: list[tuple[str, list[str]]] = []
    depth = 0
    current_title: str | None = None
    current_lines: list[str] = []

    for line in config.splitlines():
        code, delta = _code_and_brace_delta(line)
        if current_title is None and depth == 0:
            match = re.match(r"\s*menuentry\s+(['\"])(.*?)\1", code)
            if match:
                current_title = match.group(2)
                current_lines = [line]
                depth += delta
                if delta <= 0 and depth == 0:
                    blocks.append((current_title, current_lines))
                    current_title = None
                continue
        elif current_title is not None:
            current_lines.append(line)
            depth += delta
            if depth == 0:
                blocks.append((current_title, current_lines))
                current_title = None
                current_lines = []
            continue
        depth += delta

    entries: list[BootEntry] = []
    for title, lines in blocks:
        linux_args: list[str] | None = None
        initrd_args: list[str] = []
        for line in lines:
            code, _ = _code_and_brace_delta(line)
            stripped = code.strip()
            if stripped.startswith("linux ") or stripped.startswith("linuxefi "):
                linux_args = shlex.split(stripped)[1:]
            elif stripped.startswith("initrd ") or stripped.startswith("initrdefi "):
                initrd_args.extend(shlex.split(stripped)[1:])
        if not linux_args or not initrd_args:
            continue
        kernel, *args = linux_args
        ostree_args = [arg.split("=", 1)[1] for arg in args if arg.startswith("ostree=")]
        if len(ostree_args) != 1:
            continue
        # This value is a GRUB-time variable, unavailable to a UKI. It is a
        # display-mode hint and is intentionally omitted from the UKI cmdline.
        args = [arg for arg in args if arg != "DEEPIN_GFXMODE=$DEEPIN_GFXMODE"]
        if any("$" in arg for arg in args):
            raise ManagerError(f"{title}: 未处理的 GRUB 变量出现在内核参数中")
        entries.append(BootEntry(
            title=title,
            kernel=kernel,
            initrds=tuple(initrd_args),
            cmdline=" ".join(args),
            ostree=ostree_args[0],
        ))
    return entries


def _rooted(root: Path, path: str | Path) -> Path:
    candidate = Path(path)
    return root / candidate.relative_to("/") if candidate.is_absolute() else root / candidate


def _validate_entry(entry: BootEntry, root: Path) -> tuple[Path, tuple[Path, ...]]:
    if not entry.ostree.startswith("/"):
        raise ManagerError(f"{entry.title}: ostree= 必须是绝对路径")
    if ".." in Path(entry.ostree).parts:
        raise ManagerError(f"{entry.title}: ostree= 路径包含 '..'")
    checkout = _rooted(root, entry.ostree)
    if not checkout.is_dir():
        raise ManagerError(f"{entry.title}: OSTree checkout 不存在：{checkout}")

    files: list[Path] = []
    for grub_path in (entry.kernel, *entry.initrds):
        if not grub_path.startswith("/") or ".." in Path(grub_path).parts:
            raise ManagerError(f"{entry.title}: 不安全的 GRUB 启动路径：{grub_path}")
        host_path = _rooted(root, grub_path)
        if not host_path.is_file() or not os.access(host_path, os.R_OK):
            raise ManagerError(f"{entry.title}: 启动文件不存在或不可读：{host_path}")
        files.append(host_path)
    return files[0], tuple(files[1:])


def _pe_sections(path: Path) -> dict[str, bytes]:
    data = path.read_bytes()
    if len(data) < 0x40 or data[:2] != b"MZ":
        raise ManagerError("ukify 输出不是有效的 EFI/PE 文件")
    pe_offset = int.from_bytes(data[0x3C:0x40], "little")
    if data[pe_offset:pe_offset + 4] != b"PE\0\0":
        raise ManagerError("ukify 输出缺少 PE 签名")
    coff = pe_offset + 4
    section_count = int.from_bytes(data[coff + 2:coff + 4], "little")
    optional_size = int.from_bytes(data[coff + 16:coff + 18], "little")
    section_table = coff + 20 + optional_size
    sections: dict[str, bytes] = {}
    for index in range(section_count):
        pos = section_table + index * 40
        name = data[pos:pos + 8].split(b"\0", 1)[0].decode("ascii", "replace")
        size = int.from_bytes(data[pos + 16:pos + 20], "little")
        offset = int.from_bytes(data[pos + 20:pos + 24], "little")
        sections[name] = data[offset:offset + size]
    return sections


def _build_one(
    entry: BootEntry,
    kernel: Path,
    initrds: tuple[Path, ...],
    destination: Path,
    ukify: str,
    os_release: Path,
    secure_boot_key: Path | None,
    secure_boot_certificate: Path | None,
) -> Path:
    signature = hashlib.sha256(entry.cmdline.encode())
    for path in (kernel, *initrds, os_release):
        signature.update(str(path).encode())
        with path.open("rb") as stream:
            while chunk := stream.read(1024 * 1024):
                signature.update(chunk)
    digest = signature.hexdigest()[:12]
    safe_id = re.sub(r"[^A-Za-z0-9._-]", "_", entry.deployment_id)
    final_path = destination / f"deepin-{safe_id}-{digest}.efi"

    destination.mkdir(parents=True, exist_ok=True)
    if final_path.is_file():
        sections = _pe_sections(final_path)
        embedded_cmdline = sections.get(".cmdline", b"").split(b"\0", 1)[0].decode(errors="replace")
        if embedded_cmdline == entry.cmdline:
            return final_path

    fd, temp_name = tempfile.mkstemp(prefix=".deepin-uki-", suffix=".efi", dir=destination)
    os.close(fd)
    temp_path = Path(temp_name)
    try:
        cmd = [
            ukify, "build", f"--linux={kernel}",
            f"--cmdline={entry.cmdline}", f"--os-release={os_release}",
        ]
        cmd.extend(f"--initrd={initrd}" for initrd in initrds)
        if secure_boot_key or secure_boot_certificate:
            if not secure_boot_key or not secure_boot_certificate:
                raise ManagerError("Secure Boot 签名需要同时提供私钥和证书")
            cmd.extend([
                f"--secureboot-private-key={secure_boot_key}",
                f"--secureboot-certificate={secure_boot_certificate}",
            ])
        cmd.append(f"--output={temp_path}")
        subprocess.run(cmd, check=True)

        sections = _pe_sections(temp_path)
        missing = {".linux", ".initrd", ".cmdline"} - sections.keys()
        if missing:
            raise ManagerError(f"UKI 缺少必要 PE section：{', '.join(sorted(missing))}")
        embedded_cmdline = sections[".cmdline"].split(b"\0", 1)[0].decode(errors="replace")
        if embedded_cmdline != entry.cmdline:
            raise ManagerError(f"{entry.title}: UKI 中的 .cmdline 与预期不一致")

        with temp_path.open("rb") as stream:
            os.fsync(stream.fileno())
        os.replace(temp_path, final_path)
        dir_fd = os.open(destination, os.O_DIRECTORY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)
        return final_path
    finally:
        temp_path.unlink(missing_ok=True)


def reconcile(args: argparse.Namespace) -> int:
    root = Path(args.root).resolve()
    config = _rooted(root, args.grub_config)
    destination = _rooted(root, args.uki_dir)
    os_release = _rooted(root, args.os_release)
    lock_path = _rooted(root, args.lock_file)
    lock_path.parent.mkdir(parents=True, exist_ok=True)

    with lock_path.open("w") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        if not config.is_file():
            raise ManagerError(f"找不到 GRUB 配置：{config}")
        entries = parse_top_level_entries(config.read_text(encoding="utf-8"))
        if not entries:
            raise ManagerError("没有找到带 linux、initrd 和 ostree= 参数的顶层菜单项")

        # Stable deployment IDs may appear more than once; keep the first
        # top-level entry and avoid duplicate UKIs.
        unique: dict[str, BootEntry] = {}
        for entry in entries:
            unique.setdefault(entry.deployment_id, entry)

        failures = 0
        for deployment_id, entry in unique.items():
            try:
                kernel, initrds = _validate_entry(entry, root)
                output = _build_one(
                    entry, kernel, initrds, destination, args.ukify, os_release,
                    Path(args.secure_boot_key) if args.secure_boot_key else None,
                    Path(args.secure_boot_certificate) if args.secure_boot_certificate else None,
                )
                print(f"OK {deployment_id}: {output}")
            except (ManagerError, OSError, subprocess.CalledProcessError) as exc:
                failures += 1
                print(f"ERROR {deployment_id} ({entry.title}): {exc}", file=sys.stderr)
        return 1 if failures else 0


def status(args: argparse.Namespace) -> int:
    directory = _rooted(Path(args.root).resolve(), args.uki_dir)
    if not directory.is_dir():
        print(f"UKI 目录尚不存在：{directory}")
        return 0
    for path in sorted(directory.glob("deepin-*.efi")):
        print(f"{path.stat().st_size:>12}  {path.name}")
    return 0


def make_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="deepin-uki-manager",
        description="从 GRUB 顶层 OSTree 菜单项生成并管理 UKI",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)
    for name, function in (("reconcile", reconcile), ("status", status)):
        sub = subparsers.add_parser(name)
        sub.set_defaults(function=function)
        sub.add_argument("--root", default="/", help="系统根目录（默认 /，主要用于测试）")
        sub.add_argument("--grub-config", default="/boot/grub/grub.cfg")
        sub.add_argument("--uki-dir", default="/boot/xbootldr/EFI/Linux")
        if name == "reconcile":
            sub.add_argument("--ukify", default=shutil.which("ukify") or "ukify")
            sub.add_argument("--os-release", default="/etc/os-release")
            sub.add_argument("--lock-file", default="/run/lock/deepin-uki-manager.lock")
            sub.add_argument("--secure-boot-key")
            sub.add_argument("--secure-boot-certificate")
    return parser


def main() -> int:
    args = make_parser().parse_args()
    try:
        return args.function(args)
    except (ManagerError, OSError, UnicodeError) as exc:
        print(f"deepin-uki-manager: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
